const file = msg.payload;

return {
    _msgid:     msg._msgid,
    _dl:        msg._dl,
    parts:      msg.parts,
    metadata:   msg.metadata,
    _file_meta: {
        url:  file.url,
        name: file.name || "attachment",
        type: file.type || "application/octet-stream",
        size: file.size || 0
    },
    url:   file.url,
    topic: msg.topic
};

/**
 * Resolves actual Content-Type and filename from HTTP response headers
 * and writes them into _file_meta immediately after the HTTP GET.
 * Ensures Store file via global context always has correct metadata
 * regardless of what the signed URL path looks like.
 */
const headers = msg.responseHeaders || {};

const raw_ct      = headers['content-type'] || headers['Content-Type'] || msg._file_meta.type;
const actual_type = raw_ct.split(";")[0].trim();

let actual_name   = msg._file_meta.name;
const disposition = headers['content-disposition'] || headers['Content-Disposition'] || "";
const cd_match    = disposition.match(/filename\*?=['"]?(?:UTF-8'')?([^;'"\r\n]+)/i);

if (cd_match) {
    actual_name = decodeURIComponent(cd_match[1].trim());
} else if (!actual_name.includes(".")) {
    const ext_map = {
        "image/jpeg":      ".jpg",
        "image/png":       ".png",
        "image/gif":       ".gif",
        "image/webp":      ".webp",
        "application/pdf": ".pdf",
        "video/mp4":       ".mp4"
    };
    actual_name = actual_name + (ext_map[actual_type] || "");
}

msg._file_meta.type = actual_type;
msg._file_meta.name = actual_name;

node.log("Resolved: " + actual_name + " (" + actual_type + ")");

return msg;
